    paren_groups = paren_string.split()
    max_depths = []
    for group in paren_groups:
        max_depth = 0
        count = 0
        for paren in group:
            if paren == "(":
                count += 1
                max_depth = max(max_depth, count)
            elif paren == ")":
                count -= 1
