import heapq

def minPath(grid, k):
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    pq = []
    for i in range(n):
        for j in range(n):
            heapq.heappush(pq, (grid[i][j], [(i, j)], [grid[i][j]]))

    while pq:
        _, path, values = heapq.heappop(pq)
        if len(path) == k:
            return values

        last_i, last_j = path[-1]
        for di, dj in directions:
            ni, nj = last_i + di, last_j + dj
            if 0 <= ni < n and 0 <= nj < n and (ni, nj) not in path:
                new_path = path + [(ni, nj)]
                new_values = values + [grid[ni][nj]]
                heapq.heappush(pq, (sum(new_values), new_path, new_values))

    return []

def tri(n):
    def compute_tri(k, memo):
        if k in memo:
            return memo[k]
        if k == 1:
            memo[k] = 1
        elif k == 2:
            memo[k] = 1
        elif k == 3:
            memo[k] = 2
        else:
            memo[k] = compute_tri(k - 1, memo) + compute_tri(k - 2, memo) + compute_tri(k - 3, memo)
        return memo[k]

    memo = {1: 1, 2: 1, 3: 2}
    for i in range(1, n + 1):
        compute_tri(i, memo)
    return [memo[i] for i in range(1, n + 1)]

def is_nested(string):
