def do_algebra(operator, operand):
    if len(operator) != len(operand) - 1:
        raise ValueError("Number of operators must be one less than number of operands.")

    result = operand[0]
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i+1]
        elif operator[i] == '-':
            result -= operand[i+1]
        elif operator[i] == '*':
            result *= operand[i+1]
        elif operator[i] == '//':
            result //= operand[i+1]
        elif operator[i] == '**':
            result **= operand[i+1]
        else:
            raise ValueError('Unrecognized operator: {}'.format(operator[i]))

    return result
